/**
 * Universal SVG Icon component.
 * Can be used as <Icon name="commute" className="..." />
 * or as <Icon className="...">commute</Icon>
 */
export default function Icon({ name, children, fill, style, className = "", ...props }) {
  const rawKey = (name || (typeof children === "string" ? children : "")).trim();
  const iconKey = rawKey.toLowerCase();

  const isFilled = fill || (style && typeof style === "object" && /FILL\D*1/.test(style.fontVariationSettings || ""));

  let iconData = (isFilled && FILL_ICONS[iconKey]) ? FILL_ICONS[iconKey] : ICONS[iconKey];

  // Fallback if fill variant not found
  if (!iconData && isFilled) {
    iconData = ICONS[iconKey];
  }

  if (!iconData) {
    return null;
  }

  const isCustom = typeof iconData === "object" && iconData.viewBox;
  const viewBox = isCustom ? iconData.viewBox : "0 -960 960 960";
  const path = isCustom ? iconData.path : iconData;

  // Clean style to remove fontVariationSettings if present
  let cleanStyle = style;
  if (style && style.fontVariationSettings) {
    const { fontVariationSettings: _, ...rest } = style;
    cleanStyle = Object.keys(rest).length ? rest : undefined;
  }

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={viewBox}
      fill="currentColor"
      aria-hidden="true"
      className={`inline-block shrink-0 align-middle w-[1em] h-[1em] ${className}`}
      style={cleanStyle}
      {...props}
    >
      <path d={path} />
    </svg>
  );
}
